# Exact normalized lookup.
FAQ_LOOKUP = {}
for item in QUESTION_BANK:
    key = normalize_question(item["question"])
    FAQ_LOOKUP[key] = item


def lookup_verified_faq(question: str, allow_fuzzy: bool = True) -> dict | None:
    """
    Returns a verified FAQ item if the student's question matches.

    Exact normalized matching is tried first.

    A conservative fuzzy match is optional and only accepted at >= 0.93
    similarity. If no safe match is found, return None so normal RAG runs.
    """
    key = normalize_question(question)

    if not key:
        return None

    exact = FAQ_LOOKUP.get(key)
    if exact:
        return {
            **exact,
            "source": "verified_faq",
            "match_type": "exact",
            "match_score": 1.0,
        }

    if not allow_fuzzy:
        return None

    best_item = None
    best_score = 0.0

    for faq_key, item in FAQ_LOOKUP.items():
        score = SequenceMatcher(None, key, faq_key).ratio()

        if score > best_score:
            best_score = score
            best_item = item

    if best_item is not None and best_score >= 0.93:
        return {
            **best_item,
            "source": "verified_faq",
            "match_type": "fuzzy",
            "match_score": round(best_score, 4),
        }

    return None


def faq_count() -> dict:
    return {
        "question_phrasings": len(QUESTION_BANK),
        "canonical_answers": len({item["id"] for item in QUESTION_BANK}),
        "topics": len({item["topic"] for item in QUESTION_BANK}),
    }
